CREATE   VIEW [synapse_fo].[vwMainAccount]
AS
SELECT 
	T1.ACCOUNTCATEGORYREF AS ACCOUNTCATEGORYREFERENCE
	,T1.CLOSING AS CLOSING
	,T1.CONSOLIDATIONMAINACCOUNT AS DEFAULTCONSOLIDATIONACCOUNT
	,T1.CURRENCYCODE AS DEFAULTCURRENCY
	,T1.DEBITCREDITBALANCEDEMAND AS BALANCECONTROL
	,T1.DEBITCREDITCHECK AS DEBITCREDITREQUIREMENT
	,T1.DEBITCREDITPROPOSAL AS DEBITCREDITDEFAULT
	,T1.EXCHANGEADJUSTED AS FOREIGNCURRENCYREVALUATION
	,T1.FINANCIALREPORTINGEXCHANGERATETYPE AS FINANCIALREPORTINGEXCHANGERATETYPERECID
	,T1.FINANCIALREPORTINGTRANSLATIONTYPE AS FINANCIALREPORTINGCURRENCYTRANSLATIONTYPE
	,T1.LEDGERCHARTOFACCOUNTS AS CHARTOFACCOUNTSRECID
	,T1.MAINACCOUNTID AS MAINACCOUNTID
	,T1.MANDATORYPAYMENTREFERENCE AS MANDATORYPAYMENTREFERENCE
	,T1.MONETARY AS MONETARY
	,T1.NAME AS NAME
	,T1.OFFSETLEDGERDIMENSION AS OFFSETACCOUNT
	,T1.POSTINGTYPE AS POSTINGTYPE
	,T1.SRUCODE AS SRUCODE
	,T1.TYPE AS MAINACCOUNTTYPE
	,T1.USERINFOID AS USER_
	,T1.VALIDATECURRENCY AS VALIDATECURRENCY
	,T1.VALIDATEPOSTING AS VALIDATEPOSTINGTYPE
	,T1.VALIDATEUSER AS VALIDATEUSER
	,T1.REPORTINGACCOUNTTYPE AS REPORTINGACCOUNTTYPE
	,T1.RECID AS MAINACCOUNTRECID
	,T1.ADJUSTMENTMETHOD_MX AS ADJUSTMENTMETHOD
	,T1.INFLATIONADJUSTMENT_MX AS INFLATIONADJUSTMENT
	,T1.REPOMOTYPE_MX AS REPOMOTYPE
	,T1.EXCHANGEADJUSTMENTRATETYPE AS EXCHANGEADJUSTMENTRATETYPERECID
	,T1.REPORTINGEXCHANGEADJUSTMENTRATETYPE AS REPORTINGEXCHANGEADJUSTMENTRATETYPERECID
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.CREATEDBY AS CREATEDBY
	,T1.RECVERSION AS RECVERSION
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.NAME AS CHARTOFACCOUNTS
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	,T3.ACCOUNTCATEGORY AS MAINACCOUNTCATEGORY
	,T3.DESCRIPTION AS ACCOUNTCATEGORYDESCRIPTION
	,T3.ACCOUNTCATEGORYREF AS ACCOUNTCATEGORYREF
	,T3.ACCOUNTTYPE AS ACCOUNTTYPE
	,T3.RECVERSION AS RECVERSION#3
	,T3.PARTITION AS PARTITION#3
	,T3.RECID AS RECID#3
	,T4.DISPLAYVALUE AS OFFSETACCOUNTDISPLAYVALUE
	,T4.MAINACCOUNT AS MAINACCOUNT
	,T4.RECVERSION AS RECVERSION#4
	,T4.PARTITION AS PARTITION#4
	,T4.RECID AS RECID#4
	,T5.NAME AS FINANCIALREPORTINGEXCHANGERATETYPE
	,T5.RECVERSION AS RECVERSION#5
	,T5.PARTITION AS PARTITION#5
	,T5.RECID AS RECID#5
	--,T6.ISBLOCKEDFORMANUALENTRY AS DONOTALLOWMANUALENTRY
	--,T6.ISSUSPENDED AS ISSUSPENDED
	--,T6.ACTIVEFROM AS ACTIVEFROM
	--,T6.ACTIVETO AS ACTIVETO
	--,T6.PARTITION AS PARTITION#6
	--,T6.RECID AS RECID#6
	,T7.MAINACCOUNTID AS OPENINGACCOUNTID
	,T7.RECVERSION AS RECVERSION#7
	,T7.PARTITION AS PARTITION#7
	,T7.RECID AS RECID#7
	,T8.MAINACCOUNTID AS PARENTMAINACCOUNTID
	,T8.RECVERSION AS RECVERSION#8
	,T8.PARTITION AS PARTITION#8
	,T8.RECID AS RECID#8
	,T9.NAME AS EXCHANGEADJUSTMENTRATETYPE
	,T9.RECVERSION AS RECVERSION#9
	,T9.PARTITION AS PARTITION#9
	,T9.RECID AS RECID#9
	,T10.NAME AS REPORTINGEXCHANGEADJUSTMENTRATETYPE
	,T10.RECVERSION AS RECVERSION#10
	,T10.PARTITION AS PARTITION#10
	,T10.RECID AS RECID#10
FROM [synapse_fo].[MAINACCOUNT] T1
CROSS JOIN [synapse_fo].[LEDGERCHARTOFACCOUNTS] T2
LEFT OUTER JOIN [synapse_fo].[MAINACCOUNTCATEGORY] T3 ON (
		(T1.ACCOUNTCATEGORYREF = T3.ACCOUNTCATEGORYREF)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T4 ON (
		(T1.OFFSETLEDGERDIMENSION = T4.RECID)
		AND (T1.PARTITION = T4.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[EXCHANGERATETYPE] T5 ON (
		(T1.FINANCIALREPORTINGEXCHANGERATETYPE = T5.RECID)
		AND (T1.PARTITION = T5.PARTITION)
		)
/*
LEFT OUTER JOIN [synapse_fo].[DIMENSIONATTRIBUTEVALUEWITHTYPEVIEW] T6 ON (
		(
			(T1.RECID = T6.ENTITYINSTANCE)
			AND (T1.PARTITION = T6.PARTITION)
			)
		AND (T6.TYPE = 2)
		)
*/
LEFT OUTER JOIN [synapse_fo].[MAINACCOUNT] T7 ON (
		(T1.OPENINGACCOUNT = T7.RECID)
		AND (T1.PARTITION = T7.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[MAINACCOUNT] T8 ON (
		(T1.PARENTMAINACCOUNT = T8.RECID)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[EXCHANGERATETYPE] T9 ON (
		(T1.EXCHANGEADJUSTMENTRATETYPE = T9.RECID)
		AND (T1.PARTITION = T9.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[EXCHANGERATETYPE] T10 ON (
		(T1.REPORTINGEXCHANGEADJUSTMENTRATETYPE = T10.RECID)
		AND (T1.PARTITION = T10.PARTITION)
		)
WHERE (
		(T1.LEDGERCHARTOFACCOUNTS = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		)
